/// <summary>
/// One request shape for HSMobileOpsFeedbackService. ScreenshotBase64 is a JPEG.
/// </summary>
[DataContractAttribute]
class HSMobileOpsFeedbackRequest
{
    str dataAreaId;
    str userName;
    str deviceId;
    str feedbackId;
    str warehouseId;
    str appVersion;
    str deviceModel;
    str screen;
    str feedbackType;
    str message;
    str logs;
    str screenshotBase64;
    int take;
}

